starter.js:
const campo = document.querySelector('#id-aluno');
const botao = document.querySelector('#buscar');
const resultado = document.querySelector('#resultado');
const url = 'http://localhost:3000/alunos';

botao.addEventListener('click', () => {
  fetch(url)
    .then((resposta) => resposta.json())
    .then((alunos) => {
      const encontrado = alunos.find((aluno) => aluno.id === campo.value);
      resultado.textContent = encontrado ? encontrado.nome : 'Não encontrado';
    });
});

