solution.js:
const campo = document.querySelector('#idade');
const botao = document.querySelector('#validar');
const mensagem = document.querySelector('#mensagem');

botao.addEventListener('click', () => {
  const texto = campo.value.trim();
  const idade = Number(texto);

  if (texto === '' || Number.isNaN(idade)) {
    mensagem.textContent = 'Idade inválida';
  } else if (idade >= 18) {
    mensagem.textContent = 'Maior de idade';
  } else {
    mensagem.textContent = 'Menor de idade';
  }
});
